messages.content:
Game arcade endless runner bertema Cyber Highway dengan tema Neon dan kesulitan Menantang. Asumsi: koin data generik dipakai sebagai item skor tanpa modul belajar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "cyber-highway-rush", title: "Cyber Highway Rush", seed: "cyber-highway-01",
  theme: { preset: "neon" },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 420, maxSpeed: 720, accel: 10 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "firewall", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "pilar-data", w: 40, h: 70, weight: 2 },
      { type: "hazard", id: "gerbang-enkripsi", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: false },
    hazard:  { lives: -1, sfx: "hit", shake: 10 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 12, speed: 30 }
  }
});
// END_OF_MANIFEST
```
